// ============================================================
// Prepare Keyframes for Face Recognition
// ============================================================
// After ffmpeg extracts keyframes, this node creates an array
// of items — one per keyframe — so each can be sent to CompreFace.
// ============================================================

const item = $input.first();
const original = $('Mark Processing').item.json;
const mediaId = original.id;
const stdout = item.json.stdout || '0';
const keyframeCount = parseInt(stdout.trim()) || 0;

if (keyframeCount === 0) {
  // No keyframes extracted — might be a very short video
  // Send original file to face recognition anyway
  return [{
    json: {
      ...original,
      _keyframePath: original.local_path,
      _keyframeIndex: 0,
      _totalKeyframes: 1,
      _isKeyframe: false
    }
  }];
}

// Create one item per keyframe
const results = [];
for (let i = 1; i <= Math.min(keyframeCount, 5); i++) {
  const kfPath = `/home/node/media_cache/keyframes/${mediaId}_${String(i).padStart(3, '0')}.jpg`;
  results.push({
    json: {
      ...original,
      _keyframePath: kfPath,
      _keyframeIndex: i,
      _totalKeyframes: keyframeCount,
      _isKeyframe: true
    }
  });
}

return results;

// ============================================================
// Parse Face Recognition Results
// ============================================================
// CompreFace returns an array of detected faces, each with:
//   - box: {x_min, y_min, x_max, y_max, probability}
//   - subjects: [{subject, similarity}]
//
// This node:
//   1. Filters matches above the confidence threshold
//   2. Deduplicates friend names (same person in multiple keyframes)
//   3. Prepares data for database update
// ============================================================

const THRESHOLD = parseFloat($env.FACE_CONFIDENCE_THRESHOLD) || 0.85;

// Collect all results (may be from multiple keyframes for videos)
const items = $input.all();
const allFaces = [];
const friendsSet = new Set();

for (const item of items) {
  const result = item.json.result || item.json.body?.result || [];

  for (const face of result) {
    const subjects = face.subjects || [];
    const bestMatch = subjects.length > 0 ? subjects[0] : null;

    if (bestMatch && bestMatch.similarity >= THRESHOLD) {
      friendsSet.add(bestMatch.subject);
      allFaces.push({
        subject: bestMatch.subject,
        similarity: Math.round(bestMatch.similarity * 1000) / 1000,
        box: face.box,
        keyframeIndex: item.json._keyframeIndex || 0
      });
    } else if (face.box && face.box.probability > 0.8) {
      // Face detected but not recognized — log it anyway
      allFaces.push({
        subject: '_unknown',
        similarity: bestMatch ? bestMatch.similarity : 0,
        box: face.box,
        keyframeIndex: item.json._keyframeIndex || 0
      });
    }
  }
}

// Get the original media file info from the parent node using pairedItem
const original = $('Mark Processing').item.json;
const mediaId = original.id;
const friendsList = Array.from(friendsSet).sort().map(f => f.replace(/'/g, "''"));

return [{ 
  json: {
    mediaId: mediaId,
    gdriveFileId: original.gdrive_file_id || original.gdriveFileId,
    originalFilename: original.original_filename || original.originalFilename,
    isVideo: original.is_video || original.isVideo || false,
    takenAt: original.taken_at || original.takenAt,
    localPath: original.local_path || original.localPath,
    facesDetected: allFaces.length,
    facesRecognized: JSON.stringify(allFaces).replace(/'/g, "''"),
    friendsIdentified: friendsList,
    friendCount: friendsList.length,
    // For display
    friendNames: friendsList.join(', ') || 'No friends recognized',
  }
}];
